    26	/**
    27	 * Writes a JsonArray using HttpServletResponse#getWriter
    28	 * http://localhost:8080/jsondemos-servlet/array
    29	 *
    30	 * Writes a JsonArray using HttpServletResponse#getOutputStream
    31	 * http://localhost:8080/jsondemos-servlet/array?stream
    32	 *
    33	 *
    34	 * @author Jitendra Kotamraju
    35	 */
    36	@WebServlet("/array")
    37	public class ArrayServlet extends HttpServlet {
    38	    private static final JsonBuilderFactory bf = Json.createBuilderFactory(null);
    39	    private static final JsonWriterFactory wf = Json.createWriterFactory(null);
    40	
    41	    @Override
    42	    public void doGet(HttpServletRequest req, HttpServletResponse res) throws IOException {
    43	        JsonArray array = bf.createArrayBuilder()
    44	                .add(bf.createObjectBuilder()
    45	                    .add("type", "home")
    46	                    .add("number", "212 555-1234"))
    47	                .add(bf.createObjectBuilder()
    48	                    .add("type", "fax")
    49	                    .add("number", "646 555-4567"))
    50	                .build();
    51	        res.setStatus(HttpServletResponse.SC_OK);
    52	        res.setContentType("application/json");
    53	        res.setCharacterEncoding("UTF-8");
    54	
    55	        String q = req.getQueryString();
    56	        boolean isStream = q != null && q.equals("stream");
    57	        JsonWriter writer = isStream
    58	                ? wf.createWriter(res.getOutputStream())
    59	                : wf.createWriter(res.getWriter());
    60	        writer.write(array);
    61	        // not closing writer intentionally
    62	    }
    63	
    64	}
