        1	import jakarta.ws.rs.GET;
        2	import jakarta.ws.rs.Path;
        3	import jakarta.ws.rs.Produces;
        4	import jakarta.ws.rs.core.StreamingOutput;
        5	import java.io.*;
        6	import java.net.URL;
        7	
        8	/**
        9	 * Filters JSON from flicker photo search REST API
       10	 *
       11	 * {
       12	 *    photos : {
       13	 *        photo: [
       14	 *           { id: "9889087315", secret: "40aeb70c83", server: "3818",farm: 4, ..},
       15	 *           { id: "9889087315", secret: "40aeb70c83", server: "3818",farm: 4, ..}
       16	 *           ...
       17	 *        ],
       18	 *        ...
       19	 *    }
       20	 * }
       21	 *
       22	 * @author Jitendra Kotamraju
       23	 */
       24	@Path("/parser")
       25	public class ParserResource {
       26	
       27	    @GET
       28	    @Produces("text/html")
       29	    public StreamingOutput doGet() {
       30	        return new StreamingOutput() {
       31	            public void write(OutputStream os) throws IOException {
       32	                writeFlickerFeed(os);
       33	            }
       34	        };
       35	    }
       36	
       37	    private void writeFlickerFeed(OutputStream os) throws IOException {
       38	        URL url = new URL("http://api.flickr.com/services/rest/?method=flickr.photos.getRecent&api_key=221160312e1c22ec60ecf336951b0e77&format=json&nojsoncallback=1&per_page=20");
       39	        try(InputStream is = url.openStream();
       40	            JsonParser parser = Json.createParser(is);
       41	            PrintWriter ps = new PrintWriter(new OutputStreamWriter(os, "UTF-8"))) {
       42	            String id = null;
       43	            String server = null;
       44	            String secret = null;
       45	
       46	            ps.println("<html><body>");
       47	            while(parser.hasNext()) {
       48	                Event e = parser.next();
       49	                if (e == Event.KEY_NAME) {
       50	                    String str = parser.getString();
       51	                    switch (str) {
       52	                        case "id" :
       53	                            parser.next();
       54	                            id = parser.getString();
       55	                            break;
       56	                        case "farm" :
       57	                            parser.next();
       58	                            String farm = parser.getString();
       59	                            ps.println("<img src=\"http://farm"+farm+".staticflickr.com/"+server+"/"+id+"_"+secret+".jpg\">");
       60	                            break;
       61	                        case "server" :
       62	                            parser.next();
       63	                            server = parser.getString();
       64	                            break;
       65	                        case "secret" :
       66	                            parser.next();
       67	                            secret = parser.getString();
       68	                            break;
       69	                    }
       70	                }
       71	            }
       72	            ps.println("</body></html>");
       73	            ps.flush();
       74	        }
       75		}
       76	
       77	}
