 98	        this.rejectDuplicateKeys = getBooleanConfig(JsonConfig.REJECT_DUPLICATE_KEYS, config);
 99	        this.bufferPool = getBufferPool(config, defaultPool);
100	        this.config = config != null
101	                ? Collections.unmodifiableMap(copyPropertiesMap(this, config, properties)) : null;
