136	    private static BufferPool getBufferPool(Map<String, ?> config, BufferPool defaultrPool) {
137	        BufferPool pool = config != null ? (BufferPool)config.get(PROPERTY_BUFFER_POOL) : null;
138	        return pool != null ? pool : defaultrPool;
139	    }
140	
141	    private static int getIntConfig(String propertyName, Map<String, ?> config, int defaultValue) throws JsonException {
142	        // Try config Map first
143	        Integer intConfig = config != null ? getIntProperty(propertyName, config) : null;
144	        if (intConfig != null) {
145	            return intConfig;
146	        }
147	        // Try system properties as fallback.
148	        intConfig = getIntSystemProperty(propertyName);
149	        return intConfig != null ? intConfig : defaultValue;
150	    }
151	
152	    private static boolean getBooleanConfig(String propertyName, Map<String, ?> config) throws JsonException {
153	        // Try config Map first
154	        Boolean booleanConfig = config != null ? getBooleanProperty(propertyName, config) : null;
155	        if (booleanConfig != null) {
156	            return booleanConfig;
157	        }
158	        // Try system properties as fallback.
159	        return getBooleanSystemProperty(propertyName);
160	    }
