198	    private static String getSystemProperty(String propertyName) throws JsonException {
199	        if (System.getSecurityManager() != null) {
200	            return AccessController.doPrivileged(
201	                    (PrivilegedAction<String>) () -> System.getProperty(propertyName));
202	        } else {
203	            return System.getProperty(propertyName);
204	        }
