216	    // Constructor helper: Copy provider specific properties Map. Only specified properties are added.
217	    // Instance prettyPrinting and rejectDuplicateKeys variables must be initialized before
218	    // this method is called.
219	    private static Map<String, ?> copyPropertiesMap(JsonContext instance, Map<String, ?> config, String... properties) {
220	        Objects.requireNonNull(config, "Map of provider specific properties is null");
221	        if (properties == null || properties.length == 0) {
222	            return Collections.emptyMap();
223	        }
224	        Map<String, Object> newConfig = new HashMap<>(properties.length);
225	        for (String propertyName : properties) {
226	            switch (propertyName) {
227	                // Some properties need special handling.
228	                case JsonGenerator.PRETTY_PRINTING:
229	                    if (instance.prettyPrinting) {
230	                        newConfig.put(JsonGenerator.PRETTY_PRINTING, true);
231	                    }
232	                    break;
233	                case JsonConfig.REJECT_DUPLICATE_KEYS:
234	                    if (instance.rejectDuplicateKeys) {
235	                        newConfig.put(JsonConfig.REJECT_DUPLICATE_KEYS, true);
236	                    }
237	                // Rest of properties are copied without changes
238	                default:
239	                    if (config.containsKey(propertyName)) {
240	                        newConfig.put(propertyName, config.get(propertyName));
241	                    }
242	            }
243	        }
244	        return newConfig;
245	    }
