289	        BigDecimal bd = bigDecimalValue();
290	        if (bd.scale() <= bigIntegerScaleLimit) {
291	            return bd.toBigInteger();
292	        }
293	        throw new UnsupportedOperationException(
294	                String.format(
295	                        "Scale value %d of this BigInteger exceeded maximal allowed value of %d",
296	                        bd.scale(), bigIntegerScaleLimit));
297	    }
298	
299	    @Override
300	    public BigInteger bigIntegerValueExact() {
301	        BigDecimal bd = bigDecimalValue();
302	        if (bd.scale() <= bigIntegerScaleLimit) {
303	            return bd.toBigIntegerExact();
304	        }
305	        throw new UnsupportedOperationException(
306	                String.format(
307	                        "Scale value %d of this BigInteger exceeded maximal allowed value of %d",
308	                        bd.scale(), bigIntegerScaleLimit));
309	    }
310	
311	    @Override
312	    public ValueType getValueType() {
313	        return ValueType.NUMBER;
314	    }
315	
316	    @Override
317	    public int hashCode() {
318	        if (hashCode == 0) {
319	            hashCode = bigDecimalValue().hashCode();
320	        }
321	        return hashCode;
322	    }
323	
324	    @Override
325	    public boolean equals(Object obj) {
326	        if (this == obj){
327	            return true;
328	        }
329	        if (!(obj instanceof JsonNumber)) {
330	            return false;
331	        }
332	        JsonNumber other = (JsonNumber)obj;
333	        return bigDecimalValue().equals(other.bigDecimalValue());
334	    }
335	
336	    @Override
337	    public String toString() {
338	        return bigDecimalValue().toString();
339	    }
