 16	
 17	package org.eclipse.parsson;
 18	
 19	import jakarta.json.JsonException;
 20	import jakarta.json.stream.JsonLocation;
 21	import jakarta.json.stream.JsonParser;
 22	import jakarta.json.stream.JsonParsingException;
 23	import java.io.Closeable;
 24	import java.io.IOException;
 25	import java.io.Reader;
 26	import java.math.BigDecimal;
 27	import java.util.Arrays;
 28	
 29	import jakarta.json.stream.JsonParser.Event;
 30	
 31	/**
 32	 * JSON Tokenizer
 33	 *
 34	 * @author Jitendra Kotamraju
 35	 */
 36	final class JsonTokenizer implements Closeable {
 37	    // Table to look up hex ch -> value (for e.g HEX['F'] = 15, HEX['5'] = 5)
 38	    private final static int[] HEX = new int[128];
 39	    static {
 40	        Arrays.fill(HEX, -1);
 41	        for (int i='0'; i <= '9'; i++) {
 42	            HEX[i] = i-'0';
 43	        }
 44	        for (int i='A'; i <= 'F'; i++) {
 45	            HEX[i] = 10+i-'A';
 46	        }
 47	        for (int i='a'; i <= 'f'; i++) {
 48	            HEX[i] = 10+i-'a';
 49	        }
 50	    }
 51	    private final static int HEX_LENGTH = HEX.length;
 52	
 53	    private final JsonContext jsonContext;
 54	
 55	    private final Reader reader;
 56	
 57	    // Internal buffer that is used for parsing. It is also used
 58	    // for storing current string and number value token
 59	    private char[] buf;
 60	
 61	    // Indexes in buffer
 62	    //
 63	    // XXXssssssssssssXXXXXXXXXXXXXXXXXXXXXXrrrrrrrrrrrrrrXXXXXX
 64	    //    ^           ^                     ^             ^
 65	    //    |           |                     |             |
 66	    //   storeBegin  storeEnd            readBegin      readEnd
 67	    private int readBegin;
 68	    private int readEnd;
 69	    private int storeBegin;
 70	    private int storeEnd;
 71	
 72	    // line number of the current pointer of parsing char
 73	    private long lineNo = 1;
 74	
 75	    // XXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXX
 76	    // ^
 77	    // |
 78	    // bufferOffset
 79	    //
 80	    // offset of the last \r\n or \n. will be used to calculate column number
 81	    // of a token or an error. This may be outside of the buffer.
 82	    private long lastLineOffset = 0;
 83	    // offset in the stream for the start of the buffer, will be used in
 84	    // calculating JsonLocation's stream offset, column no.
 85	    private long bufferOffset = 0;
 86	
 87	    private boolean minus;
 88	    private boolean fracOrExp;
 89	    private BigDecimal bd;
 90	
 91	    enum JsonToken {
 92	        CURLYOPEN(Event.START_OBJECT, false),
 93	        SQUAREOPEN(Event.START_ARRAY, false),
 94	        COLON(null, false),
 95	        COMMA(null, false),
 96	        STRING(Event.VALUE_STRING, true),
 97	        NUMBER(Event.VALUE_NUMBER, true),
 98	        TRUE(Event.VALUE_TRUE, true),
 99	        FALSE(Event.VALUE_FALSE, true),
100	        NULL(Event.VALUE_NULL, true),
101	        CURLYCLOSE(Event.END_OBJECT, false),
102	        SQUARECLOSE(Event.END_ARRAY, false),
103	        EOF(null, false);
104	
105	        private final JsonParser.Event event;
106	        private final boolean value;
107	
108	        JsonToken(JsonParser.Event event, boolean value) {
109	            this.event = event;
110	            this.value = value;
111	        }
112	
113	        JsonParser.Event getEvent() {
114	            return event;
115	        }
116	
117	        boolean isValue() {
118	            return value;
119	        }
120	    }
121	
122	    JsonTokenizer(Reader reader, JsonContext jsonContext) {
123	        this.reader = reader;
124	        this.jsonContext = jsonContext;
125	        buf = jsonContext.bufferPool().take();
126	    }
127	
128	    private void readString() {
129	        // when inPlace is true, no need to copy chars
130	        boolean inPlace = true;
131	        storeBegin = storeEnd = readBegin;
132	
133	        do {
134	            // Write unescaped char block within the current buffer
135	            if (inPlace) {
136	                int ch;
137	                while(readBegin < readEnd && ((ch=buf[readBegin]) >= 0x20) && ch != '\\') {
138	                    if (ch == '"') {
139	                        storeEnd = readBegin++; // ++ to consume quote char
140	                        return;                 // Got the entire string
141	                    }
142	                    readBegin++;                // consume unescaped char
143	                }
144	                storeEnd = readBegin;
145	            }
146	
147	            // string may be crossing buffer boundaries and may contain
148	            // escaped characters.
149	            int ch = read();
150	            if (ch >= 0x20 && ch != 0x22 && ch != 0x5c) {
151	                if (!inPlace) {
152	                    buf[storeEnd] = (char)ch;
153	                }
154	                storeEnd++;
155	                continue;
156	            }
157	            switch (ch) {
158	                case '\\':
159	                    inPlace = false;        // Now onwards need to copy chars
160	                    unescape();
161	                    break;
162	                case '"':
163	                    return;
164	                default:
165	                    throw unexpectedChar(ch);
166	            }
167	        } while (true);
168	    }
169	
170	    private void unescape() {
171	        int ch = read();
172	        switch (ch) {
173	            case 'b':
174	                buf[storeEnd++] = '\b';
175	                break;
176	            case 't':
177	                buf[storeEnd++] = '\t';
178	                break;
179	            case 'n':
180	                buf[storeEnd++] = '\n';
181	                break;
182	            case 'f':
183	                buf[storeEnd++] = '\f';
184	                break;
185	            case 'r':
186	                buf[storeEnd++] = '\r';
187	                break;
188	            case '"':
189	            case '\\':
190	            case '/':
191	                buf[storeEnd++] = (char)ch;
192	                break;
193	            case 'u': {
194	                int unicode = 0;
195	                for (int i = 0; i < 4; i++) {
196	                    int ch3 = read();
197	                    int digit = (ch3 >= 0 && ch3 < HEX_LENGTH) ? HEX[ch3] : -1;
198	                    if (digit < 0) {
199	                        throw unexpectedChar(ch3);
200	                    }
201	                    unicode = (unicode << 4)|digit;
202	                }
203	                buf[storeEnd++] = (char)unicode;
204	                break;
205	            }
206	            default:
207	                throw unexpectedChar(ch);
208	        }
209	    }
210	
211	    // Reads a number char. If the char is within the buffer, directly
212	    // reads from the buffer. Otherwise, uses read() which takes care
213	    // of resizing, filling up the buf, adjusting the pointers
214	    private int readNumberChar() {
215	        if (readBegin < readEnd) {
216	            return buf[readBegin++];
217	        } else {
218	            storeEnd = readBegin;
219	            return read();
220	        }
221	    }
222	
223	    private void readNumber(int ch)  {
224	        storeBegin = storeEnd = readBegin-1;
225	        // sign
226	        if (ch == '-') {
227	            this.minus = true;
228	            ch = readNumberChar();
229	            if (ch < '0' || ch >'9') {
230	                throw unexpectedChar(ch);
231	            }
232	        }
233	
234	        // int
235	        if (ch == '0') {
236	            ch = readNumberChar();
237	        } else {
238	            do {
239	                ch = readNumberChar();
240	            } while (ch >= '0' && ch <= '9');
241	        }
242	
243	        // frac
244	        if (ch == '.') {
245	            this.fracOrExp = true;
246	            int count = 0;
247	            do {
248	                ch = readNumberChar();
249	                count++;
250	            } while (ch >= '0' && ch <= '9');
251	            if (count == 1) {
252	                throw unexpectedChar(ch);
253	            }
254	        }
255	
256	        // exp
257	        if (ch == 'e' || ch == 'E') {
258	            this.fracOrExp = true;
259	            ch = readNumberChar();
260	            if (ch == '+' || ch == '-') {
261	                ch = readNumberChar();
262	            }
263	            int count;
264	            for (count = 0; ch >= '0' && ch <= '9'; count++) {
265	                ch = readNumberChar();
266	            }
267	            if (count == 0) {
268	                throw unexpectedChar(ch);
269	            }
270	        }
271	        if (ch != -1) {
272	            // Only reset readBegin if eof has not been reached
273	            readBegin--;
274	            storeEnd = readBegin;
275	        }
276	    }
277	
278	    private void readTrue() {
279	        int ch1 = read();
280	        if (ch1 != 'r') {
281	            throw expectedChar(ch1, 'r');
282	        }
283	        int ch2 = read();
284	        if (ch2 != 'u') {
285	            throw expectedChar(ch2, 'u');
286	        }
287	        int ch3 = read();
288	        if (ch3 != 'e') {
289	            throw expectedChar(ch3, 'e');
290	        }
291	    }
292	
293	    private void readFalse() {
294	        int ch1 = read();
295	        if (ch1 != 'a') {
296	            throw expectedChar(ch1, 'a');
297	        }
298	        int ch2 = read();
299	        if (ch2 != 'l') {
300	            throw expectedChar(ch2, 'l');
301	        }
302	        int ch3 = read();
303	        if (ch3 != 's') {
304	            throw expectedChar(ch3, 's');
305	        }
306	        int ch4 = read();
307	        if (ch4 != 'e') {
308	            throw expectedChar(ch4, 'e');
309	        }
310	    }
311	
312	    private void readNull() {
313	        int ch1 = read();
314	        if (ch1 != 'u') {
315	            throw expectedChar(ch1, 'u');
316	        }
317	        int ch2 = read();
318	        if (ch2 != 'l') {
319	            throw expectedChar(ch2, 'l');
320	        }
321	        int ch3 = read();
322	        if (ch3 != 'l') {
323	            throw expectedChar(ch3, 'l');
324	        }
325	    }
326	
327	    /*
328	     * Could be optimized if the parser uses separate methods to match colon
329	     * etc (that would avoid the switch statement cost in certain cases)
330	     */
331	    JsonToken nextToken() {
332	        reset();
333	        int ch = read();
334	
335	        // whitespace
336	        while (ch == 0x20 || ch == 0x09 || ch == 0x0a || ch == 0x0d) {
337	            if (ch == '\r') {
338	                ++lineNo;
339	                ch = read();
340	                if (ch == '\n') {
341	                    lastLineOffset = bufferOffset+readBegin;
342	                } else {
343	                    lastLineOffset = bufferOffset+readBegin-1;
344	                    continue;
345	                }
346	            } else if (ch == '\n') {
347	                ++lineNo;
348	                lastLineOffset = bufferOffset+readBegin;
349	            }
350	            ch = read();
351	        }
352	
353	        switch (ch) {
354	            case '"':
355	                readString();
356	                return JsonToken.STRING;
357	            case '{':
358	                return JsonToken.CURLYOPEN;
359	            case '[':
360	                return JsonToken.SQUAREOPEN;
361	            case ':':
362	                return JsonToken.COLON;
363	            case ',':
364	                return JsonToken.COMMA;
365	            case 't':
366	                readTrue();
367	                return JsonToken.TRUE;
368	            case 'f':
369	                readFalse();
370	                return JsonToken.FALSE;
371	            case 'n':
372	                readNull();
373	                return JsonToken.NULL;
374	            case ']':
375	                return JsonToken.SQUARECLOSE;
376	            case '}':
377	                return JsonToken.CURLYCLOSE;
378	            case '0':
379	            case '1':
380	            case '2':
381	            case '3':
382	            case '4':
383	            case '5':
384	            case '6':
385	            case '7':
386	            case '8':
387	            case '9':
388	            case '-':
389	                readNumber(ch);
390	                return JsonToken.NUMBER;
391	            case -1:
392	                return JsonToken.EOF;
393	            default:
394	                throw unexpectedChar(ch);
395	        }
396	    }
397	
398	    boolean hasNextToken() {
399	        reset();
400	        int ch = peek();
401	
402	        // whitespace
403	        while (ch == 0x20 || ch == 0x09 || ch == 0x0a || ch == 0x0d) {
404	            if (ch == '\r') {
405	                ++lineNo;
406	                ++readBegin;
407	                ch = peek();
408	                if (ch == '\n') {
409	                    lastLineOffset = bufferOffset+readBegin+1;
410	                } else {
411	                    lastLineOffset = bufferOffset+readBegin;
412	                    continue;
413	                }
414	            } else if (ch == '\n') {
415	                ++lineNo;
416	                lastLineOffset = bufferOffset+readBegin+1;
417	            }
418	            ++readBegin;
419	            ch = peek();
420	        }
421	        return ch != -1;
422	    }
423	
424	    private int peek() {
425	        try {
426	            if (readBegin == readEnd) {     // need to fill the buffer
427	                int len = fillBuf();
428	                if (len == -1) {
429	                    return -1;
430	                }
431	                assert len != 0;
432	                readBegin = storeEnd;
433	                readEnd = readBegin+len;
434	            }
435	            return buf[readBegin];
436	        } catch (IOException ioe) {
437	            throw new JsonException(JsonMessages.TOKENIZER_IO_ERR(), ioe);
438	        }
439	    }
440	
441	    // Gives the location of the last char. Used for
442	    // JsonParsingException.getLocation
443	    JsonLocation getLastCharLocation() {
444	        // Already read the char, so subtracting -1
445	        return new JsonLocationImpl(lineNo, bufferOffset +readBegin-lastLineOffset, bufferOffset +readBegin-1);
446	    }
447	
448	    // Gives the parser location. Used for JsonParser.getLocation
449	    JsonLocation getLocation() {
450	        return new JsonLocationImpl(lineNo, bufferOffset +readBegin-lastLineOffset+1, bufferOffset +readBegin);
451	    }
452	
453	    private int read() {
454	        try {
455	            if (readBegin == readEnd) {     // need to fill the buffer
456	                int len = fillBuf();
457	                if (len == -1) {
458	                    return -1;
459	                }
460	                assert len != 0;
461	                readBegin = storeEnd;
462	                readEnd = readBegin+len;
463	            }
464	            return buf[readBegin++];
465	        } catch (IOException ioe) {
466	            throw new JsonException(JsonMessages.TOKENIZER_IO_ERR(), ioe);
467	        }
468	    }
469	
470	    private int fillBuf() throws IOException {
471	        if (storeEnd != 0) {
472	            int storeLen = storeEnd-storeBegin;
473	            if (storeLen > 0) {
474	                // there is some store data
475	                if (storeLen == buf.length) {
476	                    // buffer is full, double the capacity
477	                    char[] doubleBuf = Arrays.copyOf(buf, 2 * buf.length);
478	                    jsonContext.bufferPool().recycle(buf);
479	                    buf = doubleBuf;
480	                } else {
481	                    // Left shift all the stored data to make space
482	                    System.arraycopy(buf, storeBegin, buf, 0, storeLen);
483	                    storeEnd = storeLen;
484	                    storeBegin = 0;
485	                    bufferOffset += readBegin-storeEnd;
486	                }
487	            } else {
488	                storeBegin = storeEnd = 0;
489	                bufferOffset += readBegin;
490	            }
491	        } else {
492	            bufferOffset += readBegin;
493	        }
494	        // Fill the rest of the buf
495	        return reader.read(buf, storeEnd, buf.length-storeEnd);
496	    }
497	
498	    // state associated with the current token is no more valid
499	    private void reset() {
500	        if (storeEnd != 0) {
501	            storeBegin = 0;
502	            storeEnd = 0;
503	            bd = null;
504	            minus = false;
505	            fracOrExp = false;
506	        }
507	    }
508	
509	    String getValue() {
510	        return new String(buf, storeBegin, storeEnd-storeBegin);
511	    }
512	
513	    CharSequence getCharSequence() {
514	      int len = storeEnd - storeBegin;
515	      return new StringBuilder(len).append(buf, storeBegin, len);
516	    }
517	
518	    BigDecimal getBigDecimal() {
519	        if (bd == null) {
520	            int sourceLen = storeEnd - storeBegin;
521	            if (sourceLen > jsonContext.bigDecimalLengthLimit()) {
522	                throw new UnsupportedOperationException(
523	                        String.format(
524	                                "Number of BigDecimal source characters %d exceeded maximal allowed value of %d",
525	                                sourceLen, jsonContext.bigDecimalLengthLimit()));
526	            }
527	            bd = new BigDecimal(buf, storeBegin, sourceLen);
528	        }
529	        return bd;
530	    }
531	
532	    int getInt() {
533	        // no need to create BigDecimal for common integer values (1-9 digits)
534	        int storeLen = storeEnd-storeBegin;
535	        if (!fracOrExp && (storeLen <= 9 || (minus && storeLen <= 10))) {
536	            int num = 0;
537	            int i = minus ? 1 : 0;
538	            for(; i < storeLen; i++) {
539	                num = num * 10 + (buf[storeBegin+i] - '0');
540	            }
541	            return minus ? -num : num;
542	        } else {
543	            return getBigDecimal().intValue();
544	        }
545	    }
546	
547	    long getLong() {
548	        // no need to create BigDecimal for common integer values (1-18 digits)
549	        int storeLen = storeEnd-storeBegin;
550	        if (!fracOrExp && (storeLen <= 18 || (minus && storeLen <= 19))) {
551	            long num = 0;
552	            int i = minus ? 1 : 0;
553	            for(; i < storeLen; i++) {
554	                num = num * 10 + (buf[storeBegin+i] - '0');
555	            }
556	            return minus ? -num : num;
557	        } else {
558	            return getBigDecimal().longValue();
559	        }
560	    }
561	
562	    // returns true for common integer values (1-9 digits).
563	    // So there are cases it will return false even though the number is int
564	    boolean isDefinitelyInt() {
565	        int storeLen = storeEnd-storeBegin;
566	        return !fracOrExp && (storeLen <= 9 || (minus && storeLen <= 10));
567	    }
568	
569	    // returns true for common long values (1-18 digits).
570	    // So there are cases it will return false even though the number is long
571	    boolean isDefinitelyLong() {
572	    	int storeLen = storeEnd-storeBegin;
573	    	return !fracOrExp && (storeLen <= 18 || (minus && storeLen <= 19));
574	    }
575	
576	    boolean isIntegral() {
577	        return !fracOrExp || getBigDecimal().scale() == 0;
578	    }
579	
580	    @Override
581	    public void close() throws IOException {
582	        reader.close();
583	        jsonContext.bufferPool().recycle(buf);
584	    }
585	
586	    private JsonParsingException unexpectedChar(int ch) {
587	        JsonLocation location = getLastCharLocation();
588	        return new JsonParsingException(
589	            JsonMessages.TOKENIZER_UNEXPECTED_CHAR(ch, location), location);
590	    }
591	
592	    private JsonParsingException expectedChar(int unexpected, char expected) {
593	        JsonLocation location = getLastCharLocation();
594	        return new JsonParsingException(
595	                JsonMessages.TOKENIZER_EXPECTED_CHAR(unexpected, location, expected), location);
596	    }
597	
598	}

