305	                return builder.build();
306	            }
307	            builder.add(getValue());
308	        }
309	        throw parsingException(JsonToken.EOF, "[CURLYOPEN, SQUAREOPEN, STRING, NUMBER, TRUE, FALSE, NULL, SQUARECLOSE]");
310	    }
311	
312	    private CharSequence getCharSequence() {
313	      if (currentEvent == Event.KEY_NAME || currentEvent == Event.VALUE_STRING
314	              || currentEvent == Event.VALUE_NUMBER) {
315	          return tokenizer.getCharSequence();
316	      }
317	      throw new IllegalStateException(JsonMessages.PARSER_GETSTRING_ERR(currentEvent));
318	  }
319	
320	    private JsonObject getObject(JsonObjectBuilder builder) {
321	        while(hasNext()) {
322	            JsonParser.Event e = next();
323	            if (e == JsonParser.Event.END_OBJECT) {
324	                return builder.build();
325	            }
326	            String key = getString();
327	            next();
328	            builder.add(key, getValue());
329	        }
330	        throw parsingException(JsonToken.EOF, "[STRING, CURLYCLOSE]");
331	    }
332	
333	    @Override
334	    public JsonLocation getLocation() {
335	        return tokenizer.getLocation();
336	    }
337	
338	    public JsonLocation getLastCharLocation() {
339	        return tokenizer.getLastCharLocation();
340	    }
341	
342	    @Override
343	    public boolean hasNext() {
344	        if (stack.isEmpty() && (currentEvent != null && currentEvent.compareTo(Event.KEY_NAME) > 0)) {
345	            JsonToken token = tokenizer.nextToken();
346	            if (token != JsonToken.EOF) {
347	                throw new JsonParsingException(JsonMessages.PARSER_EXPECTED_EOF(token),
348	                        getLastCharLocation());
349	            }
350	            return false;
351	        } else if (!stack.isEmpty() && !tokenizer.hasNextToken()) {
352	            currentEvent = currentContext.getNextEvent();
353	            return false;
354	        }
355	        return true;
356	    }
357	
358	    @Override
359	    public Event next() {
360	        if (!hasNext()) {
361	            throw new NoSuchElementException();
362	        }
363	        return currentEvent = currentContext.getNextEvent();
364	    }
365	
366	    @Override
367	    public Event currentEvent() {
368	        return currentEvent;
369	    }
370	
371	    @Override
372	    public void close() {
373	        if (!closed) {
374	            try {
375	                tokenizer.close();
376	                closed = true;
377	            } catch (IOException e) {
378	                throw new JsonException(JsonMessages.PARSER_TOKENIZER_CLOSE_IO(), e);
379	            }
380	        }
381	    }
382	
383	    // Using the optimized stack impl as we don't require other things
384	    // like iterator etc.
385	    private static final class Stack {
386	        int size = 0;
387	        final int limit;
388	        private Context head;
389	
390	        Stack(int size) {
391	            this.limit = size;
392	        }
393	
394	        private void push(Context context) {
395	            if (++size >= limit) {
396	                throw new RuntimeException("Input is too deeply nested " + size);
397	            }
398	            context.next = head;
399	            head = context;
400	        }
401	
402	        private Context pop() {
403	            if (head == null) {
404	                throw new NoSuchElementException();
405	            }
406	            size--;
407	            Context temp = head;
408	            head = head.next;
409	            return temp;
410	        }
411	
412	        private Context peek() {
413	            return head;
414	        }
415	
416	        private boolean isEmpty() {
417	            return head == null;
418	        }
419	    }
420	
421	    private abstract static class Context {
422	        Context next;
423	        abstract Event getNextEvent();
424	        abstract void skip();
425	    }
426	
427	    private final class NoneContext extends Context {
428	        @Override
429	        public Event getNextEvent() {
430	            // Handle 1. {   2. [   3. value
431	            JsonToken token = tokenizer.nextToken();
432	            if (token == JsonToken.CURLYOPEN) {
433	                stack.push(currentContext);
434	                currentContext = new ObjectContext();
435	                return Event.START_OBJECT;
436	            } else if (token == JsonToken.SQUAREOPEN) {
437	                stack.push(currentContext);
438	                currentContext = new ArrayContext();
439	                return Event.START_ARRAY;
440	            } else if (token.isValue()) {
441	                return token.getEvent();
442	            }
443	            throw parsingException(token, "[CURLYOPEN, SQUAREOPEN, STRING, NUMBER, TRUE, FALSE, NULL]");
444	        }
445	
446	        @Override
447	        void skip() {
448	            // no-op
449	        }
450	    }
451	
452	    private JsonParsingException parsingException(JsonToken token, String expectedTokens) {
453	        JsonLocation location = getLastCharLocation();
454	        return new JsonParsingException(
455	                JsonMessages.PARSER_INVALID_TOKEN(token, location, expectedTokens), location);
456	    }
457	
458	    private final class ObjectContext extends Context {
459	        private boolean firstValue = true;
460	
461	        /*
462	         * Some more things could be optimized. For example, instead
463	         * tokenizer.nextToken(), one could use tokenizer.matchColonToken() to
464	         * match ':'. That might optimize a bit, but will fragment nextToken().
465	         * I think the current one is more readable.
466	         *
467	         */
468	        @Override
469	        public Event getNextEvent() {
470	            // Handle 1. }   2. name:value   3. ,name:value
471	            JsonToken token = tokenizer.nextToken();
472	            if (token == JsonToken.EOF) {
473	                switch (currentEvent) {
474	                    case START_OBJECT:
475	                        throw parsingException(token, "[STRING, CURLYCLOSE]");
476	                    case KEY_NAME:
477	                        throw parsingException(token, "[COLON]");
478	                    default:
479	                        throw parsingException(token, "[COMMA, CURLYCLOSE]");
480	                }
481	            } else if (currentEvent == Event.KEY_NAME) {
482	                // Handle 1. :value
483	                if (token != JsonToken.COLON) {
484	                    throw parsingException(token, "[COLON]");
485	                }
486	                token = tokenizer.nextToken();
487	                if (token.isValue()) {
488	                    return token.getEvent();
489	                } else if (token == JsonToken.CURLYOPEN) {
490	                    stack.push(currentContext);
491	                    currentContext = new ObjectContext();
492	                    return Event.START_OBJECT;
493	                } else if (token == JsonToken.SQUAREOPEN) {
494	                    stack.push(currentContext);
495	                    currentContext = new ArrayContext();
496	                    return Event.START_ARRAY;
497	                }
498	                throw parsingException(token, "[CURLYOPEN, SQUAREOPEN, STRING, NUMBER, TRUE, FALSE, NULL]");
499	            } else {
500	                // Handle 1. }   2. name   3. ,name
501	                if (token == JsonToken.CURLYCLOSE) {
502	                    currentContext = stack.pop();
503	                    return Event.END_OBJECT;
504	                }
505	                if (firstValue) {
506	                    firstValue = false;
507	                } else {
508	                    if (token != JsonToken.COMMA) {
509	                        throw parsingException(token, "[COMMA]");
510	                    }
511	                    token = tokenizer.nextToken();
512	                }
513	                if (token == JsonToken.STRING) {
514	                    return Event.KEY_NAME;
515	                }
516	                throw parsingException(token, "[STRING]");
517	            }
518	        }
519	
520	        @Override
521	        void skip() {
522	            JsonToken token;
523	            int depth = 1;
524	            do {
525	                token = tokenizer.nextToken();
526	                switch (token) {
527	                    case CURLYCLOSE:
528	                        depth--;
529	                        break;
530	                    case CURLYOPEN:
531	                        depth++;
532	                        break;
533	                }
534	            } while (!(token == JsonToken.CURLYCLOSE && depth == 0));
535	        }
536	
537	    }
538	
539	    private final class ArrayContext extends Context {
540	        private boolean firstValue = true;
541	
542	        // Handle 1. ]   2. value   3. ,value
543	        @Override
544	        public Event getNextEvent() {
545	            JsonToken token = tokenizer.nextToken();
546	            if (token == JsonToken.EOF) {
547	                switch (currentEvent) {
548	                    case START_ARRAY:
549	                        throw parsingException(token, "[CURLYOPEN, SQUAREOPEN, STRING, NUMBER, TRUE, FALSE, NULL]");
550	                    default:
551	                        throw parsingException(token, "[COMMA, CURLYCLOSE]");
552	                }
553	            }
554	            if (token == JsonToken.SQUARECLOSE) {
555	                currentContext = stack.pop();
556	                return Event.END_ARRAY;
557	            }
558	            if (firstValue) {
559	                firstValue = false;
560	            } else {
561	                if (token != JsonToken.COMMA) {
562	                    throw parsingException(token, "[COMMA]");
563	                }
564	                token = tokenizer.nextToken();
565	            }
566	            if (token.isValue()) {
567	                return token.getEvent();
568	            } else if (token == JsonToken.CURLYOPEN) {
569	                stack.push(currentContext);
570	                currentContext = new ObjectContext();
571	                return Event.START_OBJECT;
572	            } else if (token == JsonToken.SQUAREOPEN) {
573	                stack.push(currentContext);
574	                currentContext = new ArrayContext();
575	                return Event.START_ARRAY;
576	            }
577	            throw parsingException(token, "[CURLYOPEN, SQUAREOPEN, STRING, NUMBER, TRUE, FALSE, NULL]");
578	        }
579	
580	        @Override
581	        void skip() {
582	            JsonToken token;
583	            int depth = 1;
584	            do {
585	                token = tokenizer.nextToken();
586	                switch (token) {
587	                    case SQUARECLOSE:
588	                        depth--;
589	                        break;
590	                    case SQUAREOPEN:
591	                        depth++;
592	                        break;
593	                }
594	            } while (!(token == JsonToken.SQUARECLOSE && depth == 0));
595	        }
596	    }
597	
598	}

