 75	
 76	    private static enum Scope {
 77	        IN_NONE,
 78	        IN_OBJECT,
 79	        IN_FIELD,
 80	        IN_ARRAY
 81	    }
 82	
 83	    private final BufferPool bufferPool;
 84	    private final Writer writer;
 85	    private Context currentContext = new Context(Scope.IN_NONE);
 86	    private final Deque<Context> stack = new ArrayDeque<>();
 87	
 88	    // Using own buffering mechanism as JDK's BufferedWriter uses synchronized
 89	    // methods. Also, flushBuffer() is useful when you don't want to actually
 90	    // flush the underlying output source
 91	    private final char buf[];     // capacity >= INT_MIN_VALUE_CHARS.length
 92	    private int len = 0;
 93	    private boolean closed = false;
 94	
 95	    JsonGeneratorImpl(Writer writer, JsonContext jsonContext) {
 96	        this.bufferPool = jsonContext.bufferPool();
 97	        this.writer = writer;
 98	        this.buf = jsonContext.bufferPool().take();
 99	    }
100	
101	    JsonGeneratorImpl(OutputStream out, JsonContext jsonContext) {
102	        this(out, StandardCharsets.UTF_8, jsonContext);
103	    }
104	
105	    JsonGeneratorImpl(OutputStream out, Charset encoding, JsonContext jsonContext) {
106	        this(new OutputStreamWriter(out, encoding), jsonContext);
107	    }
