109	    @Override
110	    public void flush() {
111	        flushBuffer();
112	        try {
113	            writer.flush();
114	        } catch (IOException ioe) {
115	            throw new JsonException(JsonMessages.GENERATOR_FLUSH_IO_ERR(), ioe);
116	        }
