119	    @Override
120	    public JsonGenerator writeStartObject() {
121	        if (currentContext.scope == Scope.IN_OBJECT) {
122	            throw new JsonGenerationException(JsonMessages.GENERATOR_ILLEGAL_METHOD(currentContext.scope));
123	        }
124	        if (currentContext.scope == Scope.IN_NONE && !currentContext.first) {
125	            throw new JsonGenerationException(JsonMessages.GENERATOR_ILLEGAL_MULTIPLE_TEXT());
126	        }
127	        writeComma();
128	        writeChar('{');
129	        stack.push(currentContext);
130	        currentContext = new Context(Scope.IN_OBJECT);
131	        return this;
