312	    @Override
313	    public JsonGenerator write(String name, JsonValue value) {
314	        if (currentContext.scope != Scope.IN_OBJECT) {
315	            throw new JsonGenerationException(
316	                    JsonMessages.GENERATOR_ILLEGAL_METHOD(currentContext.scope));
317	        }
318	        switch (value.getValueType()) {
319	            case ARRAY:
320	                JsonArray array = (JsonArray)value;
321	                writeStartArray(name);
322	                for(JsonValue child: array) {
323	                    write(child);
324	                }
325	                writeEnd();
326	                break;
327	            case OBJECT:
328	                JsonObject object = (JsonObject)value;
329	                writeStartObject(name);
330	                for(Map.Entry<String, JsonValue> member: object.entrySet()) {
331	                    write(member.getKey(), member.getValue());
332	                }
333	                writeEnd();
334	                break;
335	            case STRING:
336	                JsonString str = (JsonString)value;
337	                write(name, str.getChars());
338	                break;
339	            case NUMBER:
340	                JsonNumber number = (JsonNumber)value;
341	                writeValue(name, number.toString());
342	                break;
343	            case TRUE:
344	                write(name, true);
345	                break;
346	            case FALSE:
347	                write(name, false);
348	                break;
349	            case NULL:
350	                writeNull(name);
351	                break;
352	        }
353	        return this;
354	    }
