534	    // begin, end-1 indexes represent characters that need not
535	    // be escaped
536	    //
537	    // XXXssssssssssssXXXXXXXXXXXXXXXXXXXXXXrrrrrrrrrrrrrrXXXXXX
538	    //    ^           ^                     ^             ^
539	    //    |           |                     |             |
540	    //   begin       end                   begin         end
541	    void writeEscapedString(CharSequence string) {
542	        writeChar('"');
543	        int len = string.length();
544	        for(int i = 0; i < len; i++) {
545	            int begin = i, end = i;
546	            char c = string.charAt(i);
547	            // find all the characters that need not be escaped
548	            // unescaped = %x20-21 | %x23-5B | %x5D-10FFFF
549	            while(c >= 0x20 && c <= 0x10ffff && c != 0x22 && c != 0x5c) {
550	                i++; end = i;
551	                if (i < len) {
552	                    c = string.charAt(i);
553	                } else {
554	                    break;
555	                }
556	            }
557	            // Write characters without escaping
558	            if (begin < end) {
559	                writeString(string, begin, end);
560	                if (i == len) {
561	                    break;
562	                }
563	            }
564	
565	            switch (c) {
566	                case '"':
567	                case '\\':
568	                    writeChar('\\'); writeChar(c);
569	                    break;
570	                case '\b':
571	                    writeChar('\\'); writeChar('b');
572	                    break;
573	                case '\f':
574	                    writeChar('\\'); writeChar('f');
575	                    break;
576	                case '\n':
577	                    writeChar('\\'); writeChar('n');
578	                    break;
579	                case '\r':
580	                    writeChar('\\'); writeChar('r');
581	                    break;
582	                case '\t':
583	                    writeChar('\\'); writeChar('t');
584	                    break;
585	                default:
586	                    String hex = "000" + Integer.toHexString(c);
587	                    writeString("\\u" + hex.substring(hex.length() - 4));
588	            }
589	        }
590	        writeChar('"');
591	    }
