694	    /**
695	     * Places characters representing the integer i into the
696	     * character array buf. The characters are placed into
697	     * the buffer backwards starting with the least significant
698	     * digit at the specified index (exclusive), and working
699	     * backwards from there.
700	     *
701	     * Will fail if i == Integer.MIN_VALUE
702	     */
703	    private static void fillIntChars(int i, char[] buf, int index) {
704	        int q, r;
705	        int charPos = index;
706	        char sign = 0;
707	
708	        if (i < 0) {
709	            sign = '-';
710	            i = -i;
711	        }
712	
713	        // Generate two digits per iteration
714	        while (i >= 65536) {
715	            q = i / 100;
716	            // really: r = i - (q * 100);
717	            r = i - ((q << 6) + (q << 5) + (q << 2));
718	            i = q;
719	            buf [--charPos] = DIGIT_ONES[r];
720	            buf [--charPos] = DIGIT_TENS[r];
721	        }
722	
723	        // Fall thru to fast mode for smaller numbers
724	        // assert(i <= 65536, i);
725	        for (;;) {
726	            q = (i * 52429) >>> (16+3);
727	            r = i - ((q << 3) + (q << 1));  // r = i-(q*10) ...
728	            buf [--charPos] = DIGITS[r];
729	            i = q;
730	            if (i == 0) break;
731	        }
732	        if (sign != 0) {
733	            buf [--charPos] = sign;
734	        }
735	    }
