332	                }
333	                writeEnd();
334	                break;
335	            case STRING:
336	                JsonString str = (JsonString)value;
337	                write(name, str.getChars());
338	                break;
339	            case NUMBER:
340	                JsonNumber number = (JsonNumber)value;
341	                writeValue(name, number.toString());
342	                break;
343	            case TRUE:
344	                write(name, true);
345	                break;
346	            case FALSE:
347	                write(name, false);
348	                break;
349	            case NULL:
350	                writeNull(name);
351	                break;
352	        }
353	        return this;
354	    }
