402	    private void checkContextForValue() {
403	        if ((!currentContext.first && currentContext.scope != Scope.IN_ARRAY && currentContext.scope != Scope.IN_FIELD)
404	                || (currentContext.first && currentContext.scope == Scope.IN_OBJECT)) {
405	            throw new JsonGenerationException(
