517	    @Override
518	    public void close() {
519	        if (!closed) {
520	            if (currentContext.scope != Scope.IN_NONE || currentContext.first) {
521	                throw new JsonGenerationException(JsonMessages.GENERATOR_INCOMPLETE_JSON());
522	            }
523	            flushBuffer();
524	            try {
525	                writer.close();
526	            } catch (IOException ioe) {
527	                throw new JsonException(JsonMessages.GENERATOR_CLOSE_IO_ERR(), ioe);
528	            }
529	            bufferPool.recycle(buf);
530	            closed = true;
531	        }
