 17	package org.eclipse.parsson;
 18	
 19	import jakarta.json.JsonException;
 20	import java.io.FilterInputStream;
 21	import java.io.IOException;
 22	import java.io.InputStream;
 23	import java.nio.charset.Charset;
 24	import java.nio.charset.StandardCharsets;
 25	
 26	/**
 27	 * A filter stream that detects the unicode encoding for the original
 28	 * stream
 29	 *
 30	 * @author Jitendra Kotamraju
 31	 */
 32	class UnicodeDetectingInputStream extends FilterInputStream {
 33	
 34	    private static final Charset UTF_32LE = Charset.forName("UTF-32LE");
 35	    private static final Charset UTF_32BE = Charset.forName("UTF-32BE");
 36	
 37	    private static final byte FF = (byte)0xFF;
 38	    private static final byte FE = (byte)0xFE;
 39	    private static final byte EF = (byte)0xEF;
 40	    private static final byte BB = (byte)0xBB;
 41	    private static final byte BF = (byte)0xBF;
 42	    private static final byte NUL = (byte)0x00;
 43	
 44	    private final byte[] buf = new byte[4];
 45	    private int bufLen;
 46	    private int curIndex;
 47	    private final Charset charset;
 48	
 49	    UnicodeDetectingInputStream(InputStream is) {
 50	        super(is);
 51	        charset = detectEncoding();
 52	    }
 53	
 54	    Charset getCharset() {
 55	        return charset;
 56	    }
 57	
 58	    private void fillBuf() {
 59	        int b1;
 60	        int b2;
 61	        int b3;
 62	        int b4;
 63	
 64	        try {
 65	            b1 = in.read();
 66	            if (b1 == -1) {
 67	                return;
 68	            }
 69	
 70	            b2 = in.read();
 71	            if (b2 == -1) {
 72	                bufLen = 1;
 73	                buf[0] = (byte)b1;
 74	                return;
 75	            }
 76	
 77	            b3 = in.read();
 78	            if (b3 == -1) {
 79	                bufLen = 2;
 80	                buf[0] = (byte)b1;
 81	                buf[1] = (byte)b2;
 82	                return;
 83	            }
 84	
 85	            b4 = in.read();
 86	            if (b4 == -1) {
 87	                bufLen = 3;
 88	                buf[0] = (byte)b1;
 89	                buf[1] = (byte)b2;
 90	                buf[2] = (byte)b3;
 91	                return;
 92	            }
 93	            bufLen = 4;
 94	            buf[0] = (byte)b1;
 95	            buf[1] = (byte)b2;
 96	            buf[2] = (byte)b3;
 97	            buf[3] = (byte)b4;
 98	        } catch (IOException ioe) {
 99	            throw new JsonException(JsonMessages.PARSER_INPUT_ENC_DETECT_IOERR(), ioe);
100	        }
101	    }
102	
103	    private Charset detectEncoding() {
104	        fillBuf();
105	        if (bufLen < 2) {
106	            throw new JsonException(JsonMessages.PARSER_INPUT_ENC_DETECT_FAILED());
107	        } else if (bufLen == 4) {
108	            // Use BOM to detect encoding
109	            if (buf[0] == NUL && buf[1] == NUL && buf[2] == FE && buf[3] == FF) {
110	                curIndex = 4;
111	                return UTF_32BE;
112	            } else if (buf[0] == FF && buf[1] == FE && buf[2] == NUL && buf[3] == NUL) {
113	                curIndex = 4;
114	                return UTF_32LE;
115	            } else if (buf[0] == FE && buf[1] == FF) {
116	                curIndex = 2;
117	                return StandardCharsets.UTF_16BE;
118	            } else if (buf[0] == FF && buf[1] == FE) {
119	                curIndex = 2;
120	                return StandardCharsets.UTF_16LE;
121	            } else if (buf[0] == EF && buf[1] == BB && buf[2] == BF) {
122	                curIndex = 3;
123	                return StandardCharsets.UTF_8;
124	            }
125	            // No BOM, just use JSON RFC's encoding algo to auto-detect
126	            if (buf[0] == NUL && buf[1] == NUL && buf[2] == NUL) {
127	                return UTF_32BE;
128	            } else if (buf[0] == NUL && buf[2] == NUL) {
129	                return StandardCharsets.UTF_16BE;
130	            } else if (buf[1] == NUL && buf[2] == NUL && buf[3] == NUL) {
131	                return UTF_32LE;
132	            } else if (buf[1] == NUL && buf[3] == NUL) {
133	                return StandardCharsets.UTF_16LE;
134	            }
135	        }
136	        return StandardCharsets.UTF_8;
137	    }
138	
139	    @Override
140	    public int read() throws IOException {
141	        if (curIndex < bufLen) {
142	            return buf[curIndex++];
143	        }
144	        return in.read();
145	    }
146	
147	    @Override
148	    public int read(byte b[], int off, int len) throws IOException {
149	        if (curIndex < bufLen) {
150	            if (len == 0) {
151	                return 0;
152	            }
153	            if (off < 0 || len < 0 || len > b.length -off) {
154	                throw new IndexOutOfBoundsException();
155	            }
156	            int min = Math.min(bufLen-curIndex, len);
157	            System.arraycopy(buf, curIndex, b, off, min);
158	            curIndex += min;
159	            return min;
160	        }
161	        return in.read(b, off, len);
162	    }
163	
164	}
