188	/**
189	 * char[] pool that pool instances of char[] which are expensive to create.
190	 *
191	 * @author Jitendra Kotamraju
192	 */
193	class BufferPoolImpl implements BufferPool {
194	
195	    // volatile since multiple threads may access queue reference
196	    private volatile WeakReference<ConcurrentLinkedQueue<char[]>> queue;
197	
198	    /**
199	     * Gets a new object from the pool.
