344	            protected JsonValue getValue(String name, JsonValue value, JsonValue previous) {
345	                if (previous != null) {
346	                    throw new IllegalStateException(JsonMessages.DUPLICATE_KEY(name));
347	                } else {
348	                    return value;
349	                }
350	            }
351	        },
352	        FIRST(KeyStrategy.FIRST) {
353	            @Override
354	            protected JsonValue getValue(String name, JsonValue value, JsonValue previous) {
355	                if (previous != null) {
356	                    return previous;
357	                } else {
358	                    return value;
359	                }
360	            }
361	        },
362	        LAST(KeyStrategy.LAST) {
363	            @Override
364	            protected JsonValue getValue(String name, JsonValue value, JsonValue previous) {
365	                return value;
366	            }
367	        };
368	
369	        private final KeyStrategy property;
370	
371	        private DuplicateStrategy(KeyStrategy property) {
372	            this.property = property;
373	        }
374	        
375	        private static DuplicateStrategy strategyFromProperty(Object value, boolean rejectDuplicateKeys) {
376	            if (value != null) {
377	                for (DuplicateStrategy strategy : DuplicateStrategy.values()) {
378	                    if (strategy.property.equals(value)) {
379	                        return strategy;
380	                    }
381	                }
382	            }
383	            if (rejectDuplicateKeys) {
384	                return DuplicateStrategy.NONE;
385	            } else {
386	                return DuplicateStrategy.LAST;
387	            }
388	        }
389	        
390	        protected abstract JsonValue getValue(String name, JsonValue value, JsonValue previous);
391	    }
392	}

