    29	    public ValueType getValueType() {
    30	        return ValueType.STRING;
    31	    }
    32	
    33	    @Override
    34	    public int hashCode() {
    35	        return getString().hashCode();
    36	    }
    37	
    38	    @Override
    39	    public boolean equals(Object obj) {
    40	        if (this == obj){
    41	            return true;
    42	        }
    43	        if (!(obj instanceof JsonString)) {
    44	            return false;
    45	        }
    46	        JsonString other = (JsonString)obj;
    47	        return getString().equals(other.getString());
    48	    }
    49	
    50	    @Override
    51	    public String toString() {
    52	        StringBuilder sb = new StringBuilder();
    53	        sb.append('"');
    54	
    55	        for(int i = 0; i < value.length(); i++) {
    56	            char c = value.charAt(i);
    57	            // unescaped = %x20-21 | %x23-5B | %x5D-10FFFF
    58	            if (c >= 0x20 && c <= 0x10ffff && c != 0x22 && c != 0x5c) {
    59	                sb.append(c);
    60	            } else {
    61	                switch (c) {
    62	                    case '"':
    63	                    case '\\':
    64	                        sb.append('\\'); sb.append(c);
    65	                        break;
    66	                    case '\b':
    67	                        sb.append('\\'); sb.append('b');
    68	                        break;
    69	                    case '\f':
    70	                        sb.append('\\'); sb.append('f');
    71	                        break;
    72	                    case '\n':
