    77	                        break;
    78	                    case '\t':
    79	                        sb.append('\\'); sb.append('t');
    80	                        break;
    81	                    default:
    82	                        String hex = "000" + Integer.toHexString(c);
    83	                        sb.append("\\u").append(hex.substring(hex.length() - 4));
    84	                }
    85	            }
