    17	import java.io.*;
    18	import java.net.HttpURLConnection;
    19	import java.net.URL;
    20	import java.net.URLEncoder;
    21	import java.util.*;
    22	
    23	/**
    24	 * Parses JSON from twitter search REST API using object model API.
    25	 * JSON would like :
    26	 *
    27	 * {
    28	 "   statuses": [
    29	 *     { ..., "user" : { "name" : "xxx", ...}, "text: "yyy", ... },
    30	 *     { ..., "user" : { "name" : "ppp", ...}, "text: "qqq", ... },
    31	 *     ...
    32	 *   ],
    33	 *   ...
    34	 * }
    35	 *
    36	 * This codes writes the tweets to output as follows:
    37	 * xxx: yyy
    38	 * --------
    39	 * ppp: qqq
    40	 * --------
    41	 *
    42	 * @author Jitendra Kotamraju
    43	 */
    44	public class TwitterObjectSearch {
    45	
    46	    public static void main(String... args) throws Exception {
    47	        try (InputStream is = getSearchStream();
    48	             JsonReader rdr = Json.createReader(is)) {
    49	
    50	            JsonObject obj = rdr.readObject();
    51	            JsonArray results = obj.getJsonArray("statuses");
    52	            for (JsonObject result : results.getValuesAs(JsonObject.class)) {
    53	                System.out.print(result.getJsonObject("user").getString("name", "anonymous"));
    54	                System.out.print(": ");
    55	                System.out.println(result.get("text"));
    56	                System.out.println("-----------");
    57	            }
    58	
    59	//            All the tweets are collected into Stream<String> and printed
    60	//            obj.getJsonArray("statuses").getValuesAs(JsonObject.class)
    61	//                    .stream()
    62	//                    .map(v -> v.getString("text"))
    63	//                    .forEach(s -> { System.out.println(s); } );
    64	        }
    65	    }
    66	
    67	    static InputStream getSearchStream() throws Exception {
    68	        final String searchStr = "#javaone";
    69	        String searchUrl = "https://api.twitter.com/1.1/search/tweets.json";
    70	
    71	        Properties config = new Properties();
    72	        config.load(TwitterObjectSearch.class.getResourceAsStream(
    73	                "/twitterconfig.properties"));
    74	
    75	        final String consumerKey = (String)config.get("consumer-key");
    76	        final String consumerSecret = (String)config.get("consumer-secret");
    77	        final String accessToken = (String)config.get("access-token");
    78	        final String accessTokenSecret = (String)config.get("access-token-secret");
    79	        final int timestamp = (int)(System.currentTimeMillis()/1000);
    80	
    81	        Map<String, String> map = new TreeMap<String, String>() {{
    82	            put("count", "100");
    83	            put("oauth_consumer_key", consumerKey);
    84	            put("oauth_nonce", "4b25256957d75b6370f33a4501dc5e7e"); // TODO
    85	            put("oauth_signature_method", "HMAC-SHA1");
    86	            put("oauth_timestamp", ""+timestamp);
    87	            put("oauth_token", accessToken);
    88	            put("oauth_version", "1.0");
    89	            put("q", searchStr);
    90	        }};
    91	
    92	        // Builds param string
    93	        StringBuilder paramsBuilder = new StringBuilder();
    94	        boolean first = true;
    95	        for(Map.Entry<String, String> e : map.entrySet()) {
    96	            if (!first) {
    97	                paramsBuilder.append('&');
    98	            }
    99	            first = false;
   100	            paramsBuilder.append(e.getKey());
   101	            paramsBuilder.append("=");
   102	            paramsBuilder.append(URLEncoder.encode(e.getValue(), "UTF-8"));
   103	        }
   104	        String paramsString = paramsBuilder.toString();
   105	
   106	        // builds signature string
   107	        StringBuilder signatureBuilder = new StringBuilder();
   108	        signatureBuilder.append("GET");
   109	        signatureBuilder.append('&');
   110	        signatureBuilder.append(URLEncoder.encode(searchUrl, "UTF-8"));
   111	        signatureBuilder.append('&');
   112	        signatureBuilder.append(URLEncoder.encode(paramsString, "UTF-8"));
   113	        String signatureBasedString = signatureBuilder.toString();
   114	
   115	        // Create authorization signature
   116	        Mac m = Mac.getInstance("HmacSHA1");
   117	        m.init(new SecretKeySpec((consumerSecret+"&"+accessTokenSecret).getBytes(), "HmacSHA1"));
   118	        m.update(signatureBasedString.getBytes());
   119	        byte[] res = m.doFinal();
   120	        final String oauthSig = URLEncoder.encode(DatatypeConverter.printBase64Binary(res), "UTF-8");
   121	        map.put("oauth_signature", oauthSig);
   122	        map.remove("count");
   123	        map.remove("q");
   124	
   125	        // Build Authorization header
   126	        StringBuilder authorizationBuilder = new StringBuilder();
   127	        authorizationBuilder.append("OAuth ");
   128	        first = true;
   129	        for(Map.Entry<String, String> e : map.entrySet()) {
   130	            if (!first) {
   131	                authorizationBuilder.append(',');
   132	                authorizationBuilder.append(' ');
   133	            }
   134	            first = false;
   135	            authorizationBuilder.append(e.getKey());
   136	            authorizationBuilder.append('=');
   137	            authorizationBuilder.append('"');
   138	            authorizationBuilder.append(e.getValue());
   139	            authorizationBuilder.append('"');
   140	        }
   141	
   142	        // Gets the search stream
   143	        URL url = new URL(searchUrl+"?q="+URLEncoder.encode(searchStr, "UTF-8")+
   144	                "&count=100");
   145	        HttpURLConnection con = (HttpURLConnection)url.openConnection();
   146	        con.addRequestProperty("Authorization", authorizationBuilder.toString());
   147	        return con.getInputStream();
   148	    }
   149	
   150	}
