    18	/**
    19	 * Parses JSON from twitter search REST API using streaming API.
    20	 * JSON would like :
    21	 *
    22	 * {
    23	 "   statuses": [
    24	 *     { ..., "user" : { "name" : "xxx", ...}, "text: "yyy", ... },
    25	 *     { ..., "user" : { "name" : "ppp", ...}, "text: "qqq", ... },
    26	 *     ...
    27	 *   ],
    28	 *   ...
    29	 * }
    30	 *
    31	 * This codes writes the tweets to output as follows:
    32	 * xxx: yyy
    33	 * --------
    34	 * ppp: qqq
    35	 * --------
    36	 *
    37	 * TODO need to do better, also the last tweet is repeated !
    38	 *
    39	 * @author Jitendra Kotamraju
    40	 */
    41	public class TwitterStreamSearch {
    42	
    43	    public static void main(String... args) throws Exception {
    44	        try (InputStream is = TwitterObjectSearch.getSearchStream();
    45	             JsonParser parser = Json.createParser(is)) {
    46	            int depth = 0;
    47	            String name = null;
    48	            String text = null;
    49	            while (parser.hasNext()) {
    50	                Event e = parser.next();
    51	                if (e == Event.KEY_NAME) {
    52	                    switch (parser.getString()) {
    53	                        case "name":
    54	                            if (depth == 3) {
    55	                            parser.next();
    56	                            name = parser.getString();
    57	                            }
    58	                            break;
    59	                        case "text":
    60	                            if (depth == 2) {
    61	                            parser.next();
    62	                            text = parser.getString();
    63	                            }
    64	                            break;
    65	                    }
    66	                } else if (e == Event.START_OBJECT) {
    67	                    ++depth;
    68	                } else if (e == Event.END_OBJECT) {
    69	                    --depth;
    70	                    if (depth == 1) {
    71	                        System.out.println(name+": "+text);
    72	                        System.out.println("-----------");
    73	
    74	                    }
    75	                }
    76	            }
    77	        }
    78	    }
    79	
    80	}
