    30	    JsonWriterImpl(OutputStream out, JsonContext jsonContext) {
    31	        this(out, StandardCharsets.UTF_8, jsonContext);
    32	    }
    33	
    34	    JsonWriterImpl(OutputStream out, Charset charset, JsonContext jsonContext) {
    35	        // Decorating the given stream, so that buffered contents can be
    36	        // written without actually flushing the stream.
    37	        this.os = new NoFlushOutputStream(out);
    38	        this.generator = jsonContext.prettyPrinting()
    39	                ? new JsonPrettyGeneratorImpl(os, charset, jsonContext)
    40	                : new JsonGeneratorImpl(os, charset, jsonContext);
