    44	    public void writeArray(JsonArray array) {
    45	        if (writeDone) {
    46	            throw new IllegalStateException(JsonMessages.WRITER_WRITE_ALREADY_CALLED());
    47	        }
    48	        writeDone = true;
    49	        generator.writeStartArray();
    50	        for(JsonValue value : array) {
    51	            generator.write(value);
    52	        }
    53	        generator.writeEnd();
    54	        // Flush the generator's buffered contents. This won't work for byte
    55	        // streams as intermediary OutputStreamWriter buffers.
    56	        generator.flushBuffer();
    57	        // Flush buffered contents but not the byte stream. generator.flush()
    58	        // does OutputStreamWriter#flushBuffer (package private) and underlying
    59	        // byte stream#flush(). Here underlying stream's flush() is no-op.
    60	        if (os != null) {
    61	            generator.flush();
    62	        }
    63	    }
