    65	    @Override
    66	    public void writeObject(JsonObject object) {
    67	        if (writeDone) {
    68	            throw new IllegalStateException(JsonMessages.WRITER_WRITE_ALREADY_CALLED());
    69	        }
    70	        writeDone = true;
    71	        generator.writeStartObject();
    72	        for(Map.Entry<String, JsonValue> e : object.entrySet()) {
    73	            generator.write(e.getKey(), e.getValue());
    74	        }
    75	        generator.writeEnd();
    76	        // Flush the generator's buffered contents. This won't work for byte
    77	        // streams as intermediary OutputStreamWriter buffers.
    78	        generator.flushBuffer();
    79	        // Flush buffered contents but not the byte stream. generator.flush()
    80	        // does OutputStreamWriter#flushBuffer (package private) and underlying
    81	        // byte stream#flush(). Here underlying stream's flush() is no-op.
    82	        if (os != null) {
