   101	                return;
   102	            case ARRAY:
   103	                writeArray((JsonArray) value);
   104	                return;
   105	            default:
   106	                if (writeDone) {
   107	                    throw new IllegalStateException(JsonMessages.WRITER_WRITE_ALREADY_CALLED());
   108	                }
   109	                writeDone = true;
   110	                generator.write(value);
   111	                generator.flushBuffer();
   112	                if (os != null) {
   113	                    generator.flush();
   114	                }
   115	        }
   116	    }
