    53	        generator.writeEnd();
    54	        // Flush the generator's buffered contents. This won't work for byte
    55	        // streams as intermediary OutputStreamWriter buffers.
    56	        generator.flushBuffer();
    57	        // Flush buffered contents but not the byte stream. generator.flush()
    58	        // does OutputStreamWriter#flushBuffer (package private) and underlying
