     1	package org.eclipse.parsson;
     2	
     3	import jakarta.json.*;
     4	import jakarta.json.stream.JsonLocation;
     5	import jakarta.json.stream.JsonParser;
     6	import java.math.BigDecimal;
     7	import java.util.ArrayDeque;
     8	import java.util.Deque;
     9	import java.util.Iterator;
    10	import java.util.Map;
    11	import java.util.NoSuchElementException;
    12	
    13	/**
    14	 * {@link JsonParser} implementation on top of JsonArray/JsonObject
    15	 *
    16	 * @author Jitendra Kotamraju
    17	 */
    18	class JsonStructureParser implements JsonParser {
    19	
    20	    private Scope current;
    21	    private Event state;
    22	    private final Deque<Scope> scopeStack = new ArrayDeque<>();
    23	
    24	    JsonStructureParser(JsonArray array) {
    25	        current = new ArrayScope(array);
    26	    }
    27	
    28	    JsonStructureParser(JsonObject object) {
    29	        current = new ObjectScope(object);
    30	    }
    31	
    32	    @Override
    33	    public String getString() {
    34	        switch (state) {
    35	            case KEY_NAME:
    36	                return ((ObjectScope)current).key;
    37	            case VALUE_STRING:
    38	                return ((JsonString)current.getJsonValue()).getString();
    39	            case VALUE_NUMBER:
    40	                return ((JsonNumber)current.getJsonValue()).toString();
    41	            default:
    42	                throw new IllegalStateException(JsonMessages.PARSER_GETSTRING_ERR(state));
    43	        }
    44	    }
    45	
    46	    @Override
    47	    public boolean isIntegralNumber() {
    48	        if (state == Event.VALUE_NUMBER) {
    49	            return ((JsonNumber)current.getJsonValue()).isIntegral();
    50	        }
    51	        throw new IllegalStateException(JsonMessages.PARSER_ISINTEGRALNUMBER_ERR(state));
    52	    }
    53	
    54	    @Override
    55	    public int getInt() {
    56	        if (state == Event.VALUE_NUMBER) {
    57	            return ((JsonNumber)current.getJsonValue()).intValue();
    58	        }
    59	        throw new IllegalStateException(JsonMessages.PARSER_GETINT_ERR(state));
    60	    }
    61	
    62	    @Override
    63	    public long getLong() {
    64	        if (state == Event.VALUE_NUMBER) {
    65	            return ((JsonNumber)current.getJsonValue()).longValue();
    66	        }
    67	        throw new IllegalStateException(JsonMessages.PARSER_GETLONG_ERR(state));
    68	    }
    69	
    70	    @Override
    71	    public BigDecimal getBigDecimal() {
    72	        if (state == Event.VALUE_NUMBER) {
    73	            return ((JsonNumber)current.getJsonValue()).bigDecimalValue();
    74	        }
    75	        throw new IllegalStateException(JsonMessages.PARSER_GETBIGDECIMAL_ERR(state));
    76	    }
    77	
    78	    @Override
    79	    public JsonLocation getLocation() {
    80	        return JsonLocationImpl.UNKNOWN;
    81	    }
    82	
    83	    @Override
    84	    public boolean hasNext() {
    85	        return !((state == Event.END_OBJECT || state == Event.END_ARRAY) && scopeStack.isEmpty());
    86	    }
    87	
    88	    @Override
    89	    public Event next() {
    90	        if (!hasNext()) {
    91	            throw new NoSuchElementException();
    92	        }
    93	        transition();
    94	        return state;
    95	    }
    96	
    97	    private void transition() {
    98	        if (state == null) {
    99	            state = current instanceof ArrayScope ? Event.START_ARRAY : Event.START_OBJECT;
   100	        } else {
   101	            if (state == Event.END_OBJECT || state == Event.END_ARRAY) {
   102	                current = scopeStack.pop();
   103	            }
   104	            if (current instanceof ArrayScope) {
   105	                if (current.hasNext()) {
   106	                    current.next();
   107	                    state = getState(current.getJsonValue());
   108	                    if (state == Event.START_ARRAY || state == Event.START_OBJECT) {
   109	                        scopeStack.push(current);
   110	                        current = Scope.createScope(current.getJsonValue());
   111	                    }
   112	                } else {
   113	                    state = Event.END_ARRAY;
   114	                }
   115	            } else {
   116	                // ObjectScope
   117	                if (state == Event.KEY_NAME) {
   118	                    state = getState(current.getJsonValue());
   119	                    if (state == Event.START_ARRAY || state == Event.START_OBJECT) {
   120	                        scopeStack.push(current);
   121	                        current = Scope.createScope(current.getJsonValue());
   122	                    }
   123	                } else {
   124	                    if (current.hasNext()) {
   125	                        current.next();
   126	                        state = Event.KEY_NAME;
   127	                    } else {
   128	                        state = Event.END_OBJECT;
   129	                    }
   130	                }
   131	            }
   132	        }
   133	    }
   134	
   135	    @Override
   136	    public void close() {
   137	        // no-op
   138	    }
   139	
   140	    @Override
   141	    public void skipObject() {
   142	        if (current instanceof ObjectScope) {
   143	            int depth = 1;
   144	            do {
   145	                if (state == Event.KEY_NAME) {
   146	                    state = getState(current.getJsonValue());
   147	                    switch (state) {
   148	                        case START_OBJECT:
   149	                            depth++;
   150	                            break;
   151	                        case END_OBJECT:
   152	                            depth--;
   153	                            break;
   154	                        default:
   155	                            //no-op
   156	                    }
   157	                } else {
   158	                    if (current.hasNext()) {
   159	                        current.next();
   160	                        state = Event.KEY_NAME;
   161	                    } else {
   162	                        state = Event.END_OBJECT;
   163	                        depth--;
   164	                    }
   165	                }
   166	            } while (state != Event.END_OBJECT && depth > 0);
   167	        }
   168	    }
   169	
   170	    @Override
   171	    public void skipArray() {
   172	        if (current instanceof ArrayScope) {
   173	            int depth = 1;
   174	            do {
   175	                if (current.hasNext()) {
   176	                    current.next();
   177	                    state = getState(current.getJsonValue());
   178	                    switch (state) {
   179	                        case START_ARRAY:
   180	                            depth++;
   181	                            break;
   182	                        case END_ARRAY:
   183	                            depth--;
   184	                            break;
   185	                        default:
   186	                            //no-op
   187	                    }
   188	                } else {
   189	                    state = Event.END_ARRAY;
   190	                    depth--;
   191	                }
   192	            } while (!(state == Event.END_ARRAY && depth == 0));
   193	        }
   194	    }
   195	
   196	    private static Event getState(JsonValue value) {
   197	        switch (value.getValueType()) {
   198	            case ARRAY:
   199	                return Event.START_ARRAY;
   200	            case OBJECT:
   201	                return Event.START_OBJECT;
   202	            case STRING:
   203	                return Event.VALUE_STRING;
   204	            case NUMBER:
   205	                return Event.VALUE_NUMBER;
   206	            case TRUE:
   207	                return Event.VALUE_TRUE;
   208	            case FALSE:
   209	                return Event.VALUE_FALSE;
   210	            case NULL:
   211	                return Event.VALUE_NULL;
   212	            default:
   213	                throw new JsonException(JsonMessages.PARSER_STATE_ERR(value.getValueType()));
   214	        }
   215	    }
   216	
   217	    private static abstract class Scope implements Iterator {
   218	        abstract JsonValue getJsonValue();
   219	
   220	        static Scope createScope(JsonValue value) {
   221	            if (value instanceof JsonArray) {
   222	                return new ArrayScope((JsonArray)value);
   223	            } else if (value instanceof JsonObject) {
   224	                return new ObjectScope((JsonObject)value);
   225	            }
   226	            throw new JsonException(JsonMessages.PARSER_SCOPE_ERR(value));
   227	        }
   228	    }
   229	
   230	    private static class ArrayScope extends Scope {
   231	        private final Iterator<JsonValue> it;
   232	        private JsonValue value;
   233	
   234	        ArrayScope(JsonArray array) {
   235	            this.it = array.iterator();
   236	        }
   237	
   238	        @Override
   239	        public boolean hasNext() {
   240	            return it.hasNext();
   241	        }
   242	
   243	        @Override
   244	        public JsonValue next() {
   245	            value = it.next();
   246	            return value;
   247	        }
   248	
   249	        @Override
   250	        public void remove() {
   251	            throw new UnsupportedOperationException();
   252	        }
   253	
   254	        @Override
   255	        JsonValue getJsonValue() {
   256	            return value;
   257	        }
   258	
   259	    }
   260	
   261	    private static class ObjectScope extends Scope {
   262	        private final Iterator<Map.Entry<String, JsonValue>> it;
   263	        private JsonValue value;
   264	        private String key;
   265	
   266	        ObjectScope(JsonObject object) {
   267	            this.it = object.entrySet().iterator();
   268	        }
   269	
   270	        @Override
   271	        public boolean hasNext() {
   272	            return it.hasNext();
   273	        }
   274	
   275	        @Override
   276	        public Map.Entry<String, JsonValue> next() {
   277	            Map.Entry<String, JsonValue> next = it.next();
   278	            this.key = next.getKey();
   279	            this.value = next.getValue();
   280	            return next;
   281	        }
   282	
   283	        @Override
   284	        public void remove() {
   285	            throw new UnsupportedOperationException();
   286	        }
   287	
   288	        @Override
   289	        JsonValue getJsonValue() {
   290	            return value;
   291	        }
   292	
   293	    }
   294	
   295	}
