     9	
    10	/**
    11	 * This class is an implementation of a JSON Merge Patch as specified in
    12	 * <a href="http://tools.ietf.org/html/rfc7396">RFC 7396</a>.
    13	 *
    14	 * @since 1.1
    15	 */
    16	
    17	public final class JsonMergePatchImpl implements JsonMergePatch {
    18	
    19	    private final JsonValue patch;
    20	    private final JsonContext jsonContext;
    21	
    22	    public JsonMergePatchImpl(JsonValue patch, JsonContext jsonContext) {
    23	        this.jsonContext = jsonContext;
    24	        this.patch = patch;
    25	    }
    26	
    27	    @Override
    28	    public JsonValue apply(JsonValue target) {
    29	        return mergePatch(target, patch);
    30	    }
    31	
    32	    @Override
    33	    public JsonValue toJsonValue() {
    34	        return patch;
    35	    }
    36	    /**
    37	     * Applies the specified patch to the specified target.
    38	     * The target is not modified by the patch.
    39	     *
    40	     * @param target the {@code JsonValue} to apply the patch operations
    41	     * @param patch the patch
    42	     * @return the {@code JsonValue} as the result of applying the patch
    43	     *    operations on the target.
    44	     */
    45	    private JsonValue mergePatch(JsonValue target, JsonValue patch) {
    46	
    47	        if (patch.getValueType() != JsonValue.ValueType.OBJECT) {
    48	            return patch;
    49	        }
    50	        if (target.getValueType() != JsonValue.ValueType.OBJECT) {
    51	            target = JsonValue.EMPTY_JSON_OBJECT;
    52	        }
    53	        JsonObject targetJsonObject = target.asJsonObject();
    54	        JsonObjectBuilder builder =
    55	            new JsonObjectBuilderImpl(targetJsonObject, jsonContext);
    56	        patch.asJsonObject().forEach((key, value) -> {
    57	            if (value == JsonValue.NULL) {
    58	                if (targetJsonObject.containsKey(key)) {
    59	                    builder.remove(key);
    60	                }
    61	            } else if (targetJsonObject.containsKey(key)) {
    62	                builder.add(key, mergePatch(targetJsonObject.get(key), value));
    63	            } else {
    64	                builder.add(key, mergePatch(JsonValue.EMPTY_JSON_OBJECT, value));
    65	            }
    66	        });
    67	        return builder.build();
    68	    }
    69	
    70	    /**
    71	     * Generate a JSON Merge Patch from the source and target {@code JsonValue}.
    72	     * @param source the source
    73	     * @param target the target
    74	     * @return a JSON Patch which when applied to the source, yields the target
    75	     */
    76	    static JsonValue diff(JsonValue source, JsonValue target, JsonContext jsonContext) {
    77	        if (source.getValueType() != JsonValue.ValueType.OBJECT ||
    78	                target.getValueType() != JsonValue.ValueType.OBJECT) {
    79	            return target;
    80	        }
    81	        JsonObject s = (JsonObject) source;
    82	        JsonObject t = (JsonObject) target;
    83	        JsonObjectBuilder builder = new JsonObjectBuilderImpl(jsonContext);
    84	        // First find members to be replaced or removed
    85	        s.forEach((key, value) -> {
    86	            if (t.containsKey(key)) {
    87	                // key present in both.
    88	                if (! value.equals(t.get(key))) {
    89	                    // If the values are equal, nop, else get diff for the values
    90	                    builder.add(key, diff(value, t.get(key), jsonContext));
    91	                }
    92	            } else {
    93	                builder.addNull(key);
    94	            }
    95	        });
    96	        // Then find members to be added
    97	        t.forEach((key, value) -> {
    98	            if (! s.containsKey(key))
    99	                builder.add(key, value);
   100	        });
   101	        return builder.build();
   102	    }
   103	
   104	    /**
   105	     * Compares this {@code JsonMergePatchImpl} with another object.
   106	     * @param obj the object to compare this {@code JsonMergePatchImpl} against
   107	     * @return true if the given object is a {@code JsonMergePatchImpl} with the same
   108	     * reference tokens as this one, false otherwise.
   109	     */
   110	    @Override
   111	    public boolean equals(Object obj) {
   112	        if (this == obj) {
   113	            return true;
   114	        } else if (obj == null) {
   115	            return false;
   116	        } else if (getClass() != JsonMergePatchImpl.class) {
   117	            return false;
   118	        } else {
   119	            JsonMergePatchImpl other = (JsonMergePatchImpl) obj;
   120	            return Objects.equals(patch, other.patch);
   121	        }
   122	    }
   123	
   124	    /**
   125	     * Returns the hash code value for this {@code JsonMergePatchImpl}.
   126	     *
   127	     * @return the hash code value for this {@code JsonMergePatchImpl} object
   128	     */
   129	    @Override
   130	    public int hashCode() {
   131	        return Objects.hashCode(patch);
   132	    }
   133	
   134	    /**
   135	     * Returns the JSON Patch text
   136	     * @return the JSON Patch text
   137	     */
   138	    @Override
   139	    public String toString() {
   140	        return patch.toString();
   141	    }
   142	}
