 20	 *                            .remove("/Amy/age")
 21	 *                            .build();
 22	 * </pre>
 23	 * The result is equivalent to the following JSON Patch.
 24	 * <pre>
 25	 * [
 26	 *    {"op" = "add", "path" = "/John/phones/office", "value" = "1234-567"},
 27	 *    {"op" = "remove", "path" = "/Amy/age"}
 28	 * ] </pre>
 29	 *
 30	 * @since 1.1
 31	 */
 32	public final class JsonPatchBuilderImpl implements JsonPatchBuilder {
 33	
