24	 * Filters JSON from flicker photo search REST API
25	 *
26	 * {
27	 *    photos : {
28	 *        photo: [
29	 *           { id: "9889087315", secret: "40aeb70c83", server: "3818",farm: 4, ..},
30	 *           { id: "9889087315", secret: "40aeb70c83", server: "3818",farm: 4, ..}
31	 *           ...
32	 *        ],
33	 *        ...
34	 *    }
35	 * }
36	 *
37	 * @author Jitendra Kotamraju
38	 */
39	@Path("/parser")
40	public class ParserResource {
41	
42	    @GET
43	    @Produces("text/html")
44	    public StreamingOutput doGet() {
45	        return new StreamingOutput() {
46	            public void write(OutputStream os) throws IOException {
47	                writeFlickerFeed(os);
48	            }
49	        };
50	    }
51	
52	    private void writeFlickerFeed(OutputStream os) throws IOException {
53	        URL url = new URL("http://api.flickr.com/services/rest/?method=flickr.photos.getRecent&api_key=221160312e1c22ec60ecf336951b0e77&format=json&nojsoncallback=1&per_page=20");
54	        try(InputStream is = url.openStream();
55	            JsonParser parser = Json.createParser(is);
56	            PrintWriter ps = new PrintWriter(new OutputStreamWriter(os, "UTF-8"))) {
57	            String id = null;
58	            String server = null;
59	            String secret = null;
60	
61	            ps.println("<html><body>");
62	            while(parser.hasNext()) {
63	                Event e = parser.next();
64	                if (e == Event.KEY_NAME) {
65	                    String str = parser.getString();
66	                    switch (str) {
67	                        case "id" :
68	                            parser.next();
69	                            id = parser.getString();
70	                            break;
71	                        case "farm" :
72	                            parser.next();
73	                            String farm = parser.getString();
74	                            ps.println("<img src=\"http://farm"+farm+".staticflickr.com/"+server+"/"+id+"_"+secret+".jpg\">");
75	                            break;
76	                        case "server" :
77	                            parser.next();
78	                            server = parser.getString();
79	                            break;
80	                        case "secret" :
81	                            parser.next();
82	                            secret = parser.getString();
83	                            break;
84	                    }
85	                }
86	            }
87	            ps.println("</body></html>");
88	            ps.flush();
89	        }
90		}
91	
92	}

